val claim = lockRecords.filter(_.lockable === key).forUpdate.result.flatMap { rows =>
  if (rows.exists(_.owner != sessionId)) DBIO.failed(Locked(rows.head.owner))
  else lockRecords.insertOrUpdate(LockRecord(key, sessionId, Instant.now()))
}.transactionally
